  void UpdateClues(){int mask=0;var list=State.Fixture.Clues;for(int i=0;i<list.Count;i++){var p=list[i].Position;if(LabNavigation.Distance(Player,p)>32)continue;bool visible=false;for(int y=(int)p.Y-3;y<=(int)p.Y+3;y++)for(int x=(int)p.X-3;x<=(int)p.X+3;x++)if(!State.World.IsSolid(x,y)&&State.Discovery.Shown(x,y))visible=true;if(visible)mask|=1<<i;}if(mask==clueMask||clues==null)return;clueMask=mask;clues.Data.Clear();for(int i=0;i<list.Count;i++)if((mask&(1<<i))!=0){var p=list[i].Position;Stage50Preview.Stroke(clues.Data,new Point2(p.X-.5,p.Y+.2),p,.045);Stage50Preview.Stroke(clues.Data,p,new Point2(p.X+.4,p.Y-.2),.045);}clues.Dirty=true;}
