  public string Inspect(){var s=new System.Text.StringBuilder();for(int l=0;l<3;l++){s.AppendLine(State.Fixture.Landmarks[l].Id+" cached="+groundShown[l]+" calculated="+StructureMesh.GroundVisible(State.Fixture.Landmarks[l],State.Discovery));foreach(var c in State.Fixture.Landmarks[l].Contacts)for(int y=c.Y-7;y<=c.Y+7;y++)for(int x=c.X-7;x<=c.X+7;x++)if(!State.World.IsSolid(x,y)&&State.Discovery.Shown(x,y)){s.AppendLine("known floor "+x+","+y+" indexed="+State.Index.ByCell.ContainsKey(y*State.World.Width+x)+" visual="+State.Discovery.Visual.Contains(y*State.World.Width+x));goto next;}next:;}foreach(var b in batches)s.AppendLine(b.Data.Name+" landmark="+b.Landmark+" rendered="+b.Renderer.enabled);return s.ToString();}
