  readonly List<ElevatedBatch> elevated=new List<ElevatedBatch>();Material elevatedMaterial;MaterialPropertyBlock elevatedBlock;public int ElevatedOwnedMeshes=>elevated.Count;public int EncounterViolations;public double ProjectionMs;readonly double[] previousAttacks=new double[32];
  void ConfigureTerrainSemantics(){var f=State.Fixture;var boxes=new List<Vector4>();foreach(var land in f.Landmarks){foreach(var contact in land.Contacts){double x0=double.MaxValue,y0=x0,x1=double.MinValue,y1=x1;foreach(var cell in land.Footprint){var near=land.Contacts[0];foreach(var candidate in land.Contacts)if(Math.Abs(candidate.X-cell.X)+Math.Abs(candidate.Y-cell.Y)<Math.Abs(near.X-cell.X)+Math.Abs(near.Y-cell.Y))near=candidate;if(!near.Equals(contact))continue;x0=Math.Min(x0,cell.X-.75);y0=Math.Min(y0,cell.Y-.75);x1=Math.Max(x1,cell.X+1.75);y1=Math.Max(y1,cell.Y+1.75);}if(x0<double.MaxValue)boxes.Add(new Vector4((float)(x0-f.X),(float)(y0-f.Y),(float)(x1-f.X),(float)(y1-f.Y)));}}// Bone has three contact cells sharing one small footprint; merge its bounds below.
   var bone=f.Landmarks[2];double bx0=double.MaxValue,by0=bx0,bx1=double.MinValue,by1=bx1;foreach(var c in bone.Footprint){bx0=Math.Min(bx0,c.X-.75-f.X);by0=Math.Min(by0,c.Y-.75-f.Y);bx1=Math.Max(bx1,c.X+1.75-f.X);by1=Math.Max(by1,c.Y+1.75-f.Y);}while(boxes.Count>4)boxes.RemoveAt(boxes.Count-1);boxes.Add(new Vector4((float)bx0,(float)by0,(float)bx1,(float)by1));Shader.SetGlobalVectorArray("_SG55_ContactBounds",boxes.ToArray());string[] keys={"StoneUpper","StoneLower","RootUpper","RootLower","BoneUpper","BoneLower","Ink"};string[] colors={"StoneBase","StoneShadow","RootBase","RootShadow","BoneLimestone","BoneShadow","InkBlack"};for(int i=0;i<keys.Length;i++)Shader.SetGlobalColor("_SG55_"+keys[i],ElevatedMesh.VertexColor(palette.Color(colors[i])));}
  void ConfigureDiscovery(){if(State==null)return;State.Discovery.FastChambers=reveal!=0;State.Discovery.MaxReleases=reveal==0?32:256;State.Discovery.ImmediateDistance=reveal==0?0:8;}
