  void AddElevated(ElevatedPath path,int landmark){var go=new GameObject("Stage55 elevated "+path.Id){hideFlags=HideFlags.DontSave};go.transform.SetParent(transform,false);var mesh=new Mesh{name=go.name,hideFlags=HideFlags.DontSave};go.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=elevatedMaterial;rr.sortingOrder=path.Overhead?40:18;rr.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var b=new ElevatedBatch{Path=path,Mesh=mesh,Renderer=rr,Landmark=landmark};BuildBatch(b);elevated.Add(b);}
  void BuildBatch(ElevatedBatch b){b.Data.Build(b.Path,palette,State.Fixture.Materials[b.Landmark],State.World,State.Fixture.Landmarks[b.Landmark],b.Landmark==1);b.Data.Upload(b.Mesh,new Point2(State.World.Width*.5,State.World.Height*.5));b.Dirty=false;}
  void MarkElevated(TerrainCellChange c){foreach(var b in elevated){if(b.Landmark!=1)continue;foreach(var s in b.Path.Sections)if(Math.Abs(s.Left.Ground.X-c.X)<10&&Math.Abs(s.Left.Ground.Y-c.Y)<10){b.Dirty=true;break;}}}
  void UpdateElevated(){long t=System.Diagnostics.Stopwatch.GetTimestamp();bool changed=false;foreach(var b in elevated)if(b.Dirty){BuildBatch(b);changed=true;}if(changed){ElevatedAssemblyMs=StreamingGeometry.Elapsed(t);ElevatedBuilds++;}}
  bool StructureKnown(ElevatedBatch b){if(b.Landmark==0)return true;var land=State.Fixture.Landmarks[b.Landmark];return groundShown[b.Landmark];}
  void DrawElevated(){long start=System.Diagnostics.Stopwatch.GetTimestamp();foreach(var b in elevated){b.Bounds=b.Data.Bounds(Live.Snapshot,legacyProjection);double w=CameraStudy.DisplayWidth,h=w/(16.0/9);bool visible=Live.Ready&&b.Data.Indices.Count>0&&StructureKnown(b)&&LabPresentation.Intersects(b.Bounds,w,h);b.Renderer.enabled=visible;if(!visible)continue;var box=new Bounds(new Vector3((float)((b.Bounds.Min.X+b.Bounds.Max.X)*.5),(float)(-(b.Bounds.Min.Y+b.Bounds.Max.Y)*.5)),new Vector3((float)(b.Bounds.Max.X-b.Bounds.Min.X),(float)(b.Bounds.Max.Y-b.Bounds.Min.Y),.1f));box.Expand(.002f);b.Mesh.bounds=box;float alpha=1;if(cutaway&&b.Path.Overhead&&StructureMesh.Occludes(b.Bounds,Live.Snapshot,Player,Stage50Preview.VisualBounds(Player,1,0),0))alpha=.24f;if(cutaway&&b.Path.Overhead)for(int actor=0;actor<Lab.encounterCount;actor++){var a=Lab.Actors[actor];if(Lab.PresentationAllowed(a.Position)&&StructureMesh.Occludes(b.Bounds,Live.Snapshot,a.Position,Stage50Preview.VisualBounds(a.Position,a.Size,a.Kind),0))alpha=.24f;}elevatedBlock.SetFloat("_Alpha",alpha);elevatedBlock.SetFloat("_Legacy",legacyProjection?1:0);b.Renderer.SetPropertyBlock(elevatedBlock);}ProjectionMs=StreamingGeometry.Elapsed(start);}
  public void AdvanceEncounters(double dt){long t=System.Diagnostics.Stopwatch.GetTimestamp();for(int i=0;i<Lab.encounterCount;i++){previousAttacks[i]=Lab.Actors[i].Attacks;Lab.Actors[i].AttackReadable=AttackReadable;}Lab.Advance(dt);for(int i=0;i<Lab.encounterCount;i++)if(Lab.Actors[i].Attacks>previousAttacks[i]&&!EncounterReadability.Allowed(State.Discovery,Lab.Actors[i],Player,Lab.tuning.Reach(Lab.Actors[i].Attack)))EncounterViolations++;EncounterMs=StreamingGeometry.Elapsed(t);}
  public bool AttackReadable(LabActor actor,Point2 player){bool allowed=EncounterReadability.Allowed(State.Discovery,actor,player,Lab.tuning.Reach(actor.Attack));if(!allowed)BlockedAttacks++;return allowed;}
  void DiagnosticsGUI(){if(!debug||Live.Snapshot==null)return;foreach(var b in elevated){if(!b.Renderer.enabled)continue;var bounds=b.Bounds;DrawScreenBox(bounds,palette.Color("FloorPlumShadow"));for(int i=0;i<b.Path.Sections.Length;i++){var s=b.Path.Sections[i];var ground=Live.Snapshot.Project(s.Left.Ground);var elevatedPoint=legacyProjection?ElevatedProjection.Legacy(Live.Snapshot,s.Left):ElevatedProjection.Project(Live.Snapshot,s.Left);Dot(ground,Color.green,5);Dot(elevatedPoint,Color.cyan,4);}}}
  Vector2 ScreenPoint(Point2 p){var v=Live.previewCamera.WorldToScreenPoint(new Vector3((float)p.X,(float)-p.Y));return new Vector2(v.x,Screen.height-v.y);}
  void Dot(Point2 p,Color color,float size){var q=ScreenPoint(p);var old=GUI.color;GUI.color=color;GUI.DrawTexture(new Rect(q.x-size*.5f,q.y-size*.5f,size,size),Texture2D.whiteTexture);GUI.color=old;}
  void DrawScreenBox(ProjectionBounds b,Color color){var a=ScreenPoint(b.Min);var z=ScreenPoint(b.Max);var old=GUI.color;GUI.color=color;GUI.DrawTexture(new Rect(a.x,a.y,z.x-a.x,1),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(a.x,z.y,z.x-a.x,1),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(a.x,a.y,1,z.y-a.y),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(z.x,a.y,1,z.y-a.y),Texture2D.whiteTexture);GUI.color=old;}
  public string ElevatedDiagnostics(){var s=new System.Text.StringBuilder();s.AppendLine("groundX,groundY,height,projectedX,projectedY,legacyX,legacyY");foreach(var b in elevated){s.AppendLine(b.Path.Id+" visible="+b.Renderer.enabled+" triangles="+b.Data.Indices.Count/3);foreach(var section in b.Path.Sections){var v=section.Left;var p=ElevatedProjection.Project(Live.Snapshot,v);var old=ElevatedProjection.Legacy(Live.Snapshot,v);s.AppendLine($"{v.Ground.X:R},{v.Ground.Y:R},{v.Height:R},{p.X:R},{p.Y:R},{old.X:R},{old.Y:R}");}}return s.ToString();}

  bool shutDown;
  void OnDestroy()=>Shutdown();
  public void Shutdown(){if(shutDown)return;shutDown=true;if(State!=null)State.World.Changed-=OnTerrainChange;State?.Dispose();ClearElevated();ClearBatches();foreach(var m in ownedMaterials)DestroyOwned(m);}
 }
}
